steps.command:
cat > /srv/app/reload.pl <<'PERLEOF'
use strict; use warnings;
my $CONF = "/etc/app/app.conf";
my $STOP = "/srv/app/stop.flag";
my @pids;
for my $i (0..1) {
    my $pid = fork(); die "fork: $!" unless defined $pid;
    if (!$pid) {
        my $gen = 0;
        $SIG{HUP} = sub {
            $gen++;
            open(my $c, '<', $CONF) or return;
            my $data = do { local $/; <$c> }; close $c;
            $data =~ s/\n/ /g; $data =~ s/^\s+|\s+$//g;
            open(my $l, '>>', "/srv/app/worker-$i.log") or return;
            print $l "reload $gen $data\n"; close $l;
        };
        open(my $l, '>>', "/srv/app/worker-$i.log"); print $l "start\n"; close $l;
        for (1..40) { select(undef, undef, undef, 0.1); last if -e $STOP }
        exit 0;
    }
    push @pids, $pid;
}
select(undef, undef, undef, 0.8);
open(my $c, '>', $CONF) or die $!; print $c "workers=2\ntimeout=45\n"; close $c;
kill 'HUP', $_ for @pids;
select(undef, undef, undef, 0.8);
open(my $s, '>', $STOP) or die $!; print $s "stop\n"; close $s;
waitpid($_, 0) for @pids;
print "workers reloaded config and exited\n";
PERLEOF
perl -c /srv/app/reload.pl
